from __future__ import annotations

from tvm.target import Target

from tilelang.backend.target import register_target_detector


def _target_ffi_api():
    from tilelang import _ffi_api

    return _ffi_api


def check_maca_availability() -> bool:
    """
    Check if MACA is available on the system by locating the MACA path.
    Returns:
        bool: True if MACA is available, False otherwise.
    """
    try:
        from tilelang.contrib import mxcc

        mxcc.find_maca_path()
        return True
    except Exception:
        return False


def _detect_maca_target() -> Target | str | None:
    import torch

    if torch.version.hip is not None:
        return None
    if not check_maca_availability():
        return None

    return Target("maca")


def target_is_maca(target: Target) -> bool:
    return _target_ffi_api().TargetIsMaca(target)


def target_has_async_copy(target: Target) -> bool:
    return _target_ffi_api().TargetHasAsyncCopy(target)


register_target_detector("maca", _detect_maca_target, override=True)

from __future__ import annotations

from tvm.target import Target

from tilelang.backend.execution_backend import ExecutionBackendSpec, register_execution_backend


def _is_cutedsl_target(target: Target) -> bool:
    return target.kind.name == "maca" and "cutedsl" in target.keys


def _is_plain_maca_target(target: Target) -> bool:
    return target.kind.name == "maca" and "cutedsl" not in target.keys


def _is_mcrtc_available() -> bool:
    try:
        from tilelang.jit.adapter.mcrtc import is_mcrtc_available
    except ImportError:
        return False
    return bool(is_mcrtc_available)


def _is_cutedsl_available() -> bool:
    try:
        from tilelang.jit.adapter.cutedsl.checks import check_cutedsl_available

        check_cutedsl_available()
    except ImportError:
        return False
    return True


register_execution_backend(
    "maca",
    ExecutionBackendSpec(
        "tvm_ffi",
        supports_target=_is_plain_maca_target,
        enable_host_codegen=True,
        enable_device_compile=True,
    ),
    override=True,
)
register_execution_backend(
    "maca",
    ExecutionBackendSpec("mcrtc", is_available=_is_mcrtc_available, supports_target=_is_plain_maca_target),
    override=True,
)
register_execution_backend(
    "maca",
    ExecutionBackendSpec("cython", supports_target=_is_plain_maca_target),
    override=True,
)
register_execution_backend(
    "maca",
    ExecutionBackendSpec("cutedsl", is_available=_is_cutedsl_available, supports_target=_is_cutedsl_target),
    override=True,
)

from __future__ import annotations

import warnings

from tvm import tirx

import tilelang.language as T
from tilelang.maca.target import check_maca_availability
from tilelang.language.eager.builder import Builder, macro

_IS_MACA_AVAILABLE = check_maca_availability()


def get_stack_str(msg, stacklevel=1):
    stack = Builder.current().get_fileline_stack(stacklevel)
    msg = msg + "\n"
    for fileline, lineno, macro_name in stack:
        msg += f"  at {fileline}:{lineno} in {macro_name}\n"
    return msg


@macro
def device_assert(condition: tirx.PrimExpr, msg: str = "", no_stack_info=False):
    """
    Device-side assert emulation for MACA targets.
    """
    if _IS_MACA_AVAILABLE:
        if no_stack_info:
            if msg == "":
                T.call_intrin("void", tirx.op.Op.get("tl.device_assert"), condition)
            else:
                warnings.warn("Non-empty msg may slightly slow down the kernel", stacklevel=2)
                T.call_intrin("void", tirx.op.Op.get("tl.device_assert_with_msg"), condition, msg)
        else:
            T.call_intrin("void", tirx.op.Op.get("tl.device_assert_with_msg"), condition, get_stack_str(msg, stacklevel=2))

from __future__ import annotations

from collections.abc import Callable, Mapping
from dataclasses import dataclass
from typing import Literal

from tvm.target import Target

TargetConfig = dict[str, object]
TargetInput = str | Mapping[str, object] | Target
TargetLike = str | TargetConfig | Target
TargetDetector = Callable[[], TargetInput | None]
TargetNormalizer = Callable[[TargetLike], TargetInput | None]


@dataclass(frozen=True, slots=True)
class TargetDetectorSpec:
    name: str
    detect: TargetDetector


@dataclass(frozen=True, slots=True)
class TargetNormalizerSpec:
    name: str
    normalize: TargetNormalizer


_TARGET_DETECTORS: dict[str, TargetDetectorSpec] = {}
_TARGET_NORMALIZERS: dict[str, TargetNormalizerSpec] = {}


def register_target_detector(
    name: str,
    detect: TargetDetector,
    *,
    override: bool = False,
) -> TargetDetectorSpec:
    if name in _TARGET_DETECTORS and not override:
        raise ValueError(f"Target detector {name!r} is already registered")
    spec = TargetDetectorSpec(name=name, detect=detect)
    _TARGET_DETECTORS[name] = spec
    return spec


def register_target_normalizer(
    name: str,
    normalize: TargetNormalizer,
    *,
    override: bool = False,
) -> TargetNormalizerSpec:
    if name in _TARGET_NORMALIZERS and not override:
        raise ValueError(f"Target normalizer {name!r} is already registered")
    spec = TargetNormalizerSpec(name=name, normalize=normalize)
    _TARGET_NORMALIZERS[name] = spec
    return spec


def _normalize_registered_target(target: TargetLike) -> TargetInput | None:
    for spec in _TARGET_NORMALIZERS.values():
        normalized = spec.normalize(target)
        if normalized is not None:
            return normalized
    return None


def auto_detect_target() -> TargetInput:
    errors: list[str] = []
    for spec in _TARGET_DETECTORS.values():
        try:
            detected = spec.detect()
        except Exception as err:
            errors.append(f"{spec.name}: {err}")
            continue
        if detected is not None:
            return detected

    details = f" Tried: {', '.join(errors)}." if errors else ""
    raise ValueError(f"No registered target detector found an available target.{details}")


def list_target_detectors() -> tuple[str, ...]:
    return tuple(_TARGET_DETECTORS)


def _validate_manual_target(target: TargetLike) -> TargetInput:
    normalized = _normalize_registered_target(target)
    if normalized is not None:
        return normalized

    if isinstance(target, Target):
        return target
    if isinstance(target, dict):
        try:
            Target(target)
        except Exception as err:
            raise AssertionError(f"Target {target} is not supported. Pass a valid target config dict.") from err
        return target
    if isinstance(target, str):
        normalized_target = target.strip()
        if not normalized_target:
            raise AssertionError(f"Target {target} is not supported")
        try:
            Target(normalized_target)
        except Exception as err:
            raise AssertionError(
                f"Target {target} is not supported. Pass target options as a dict when the target needs attributes."
            ) from err
        return normalized_target
    raise AssertionError(f"Target {target} is not supported")


def _finalize_target(target: TargetInput, *, return_object: bool) -> str | Mapping[str, object] | Target:
    if isinstance(target, (str, dict, Target)):
        normalized = _normalize_registered_target(target)
        if normalized is not None:
            target = normalized
    if return_object and not isinstance(target, Target):
        return Target(target)
    return target


def determine_target(target: TargetLike | Literal["auto"] = "auto", return_object: bool = False) -> str | Mapping[str, object] | Target:
    """
    Determine and validate the target for compilation.

    Target detection and normalization is provided by registered target modules.
    """
    if target == "auto":
        current_target = Target.current(allow_none=True)
        return_var = current_target if current_target is not None else auto_detect_target()
    else:
        return_var = _validate_manual_target(target)

    return _finalize_target(return_var, return_object=return_object)

from __future__ import annotations

from collections.abc import Callable
from dataclasses import dataclass
from importlib import import_module

from tvm.target import Target

TargetPredicate = Callable[[Target], bool]
AvailabilityCheck = Callable[[], bool]

_CANONICAL_EXECUTION_BACKENDS = {
    "dlpack": "tvm_ffi",
}


def _always_available() -> bool:
    return True


def canonicalize_execution_backend(name: str | None) -> str | None:
    if name is None:
        return None
    key = str(name).lower()
    return _CANONICAL_EXECUTION_BACKENDS.get(key, key)


@dataclass(frozen=True, slots=True)
class ExecutionBackendSpec:
    name: str
    is_available: AvailabilityCheck = _always_available
    supports_target: TargetPredicate | None = None
    enable_host_codegen: bool = False
    enable_device_compile: bool = False

    def matches(self, target: Target) -> bool:
        return True if self.supports_target is None else self.supports_target(target)


_EXECUTION_BACKENDS: dict[str, list[ExecutionBackendSpec]] = {}
_LAZY_EXECUTION_BACKENDS: dict[str, str] = {}
_LOADED_EXECUTION_BACKENDS: set[str] = set()


def register_execution_backend(
    target_kind: str,
    spec: ExecutionBackendSpec,
    *,
    override: bool = False,
) -> ExecutionBackendSpec:
    specs = _EXECUTION_BACKENDS.setdefault(target_kind, [])
    if override:
        specs[:] = [item for item in specs if item.name != spec.name]
    elif any(item.name == spec.name for item in specs):
        raise ValueError(f"Execution backend {spec.name!r} is already registered for target kind {target_kind!r}")
    specs.append(spec)
    return spec


def register_lazy_execution_backends(target_kind: str, import_path: str) -> None:
    _LAZY_EXECUTION_BACKENDS[target_kind] = import_path


def _ensure_execution_backends_loaded(target_kind: str) -> None:
    if target_kind in _LOADED_EXECUTION_BACKENDS:
        return
    import_path = _LAZY_EXECUTION_BACKENDS.get(target_kind)
    if import_path is not None:
        import_module(import_path)
    _LOADED_EXECUTION_BACKENDS.add(target_kind)


def _matching_specs(target: Target, *, include_unavailable: bool) -> list[ExecutionBackendSpec]:
    target_kind = target.kind.name
    _ensure_execution_backends_loaded(target_kind)
    specs = [spec for spec in _EXECUTION_BACKENDS.get(target_kind, ()) if spec.matches(target)]
    if not include_unavailable:
        specs = [spec for spec in specs if spec.is_available()]
    return specs


def allowed_backends_for_target(target: Target, *, include_unavailable: bool = True) -> list[str]:
    return [spec.name for spec in _matching_specs(target, include_unavailable=include_unavailable)]


def _format_options(options: list[str]) -> str:
    return ", ".join(options) if options else "<none>"


def resolve_execution_backend(requested: str | None, target: Target) -> str:
    return resolve_execution_backend_spec(requested, target).name


def resolve_execution_backend_spec(requested: str | None, target: Target) -> ExecutionBackendSpec:
    requested_name = canonicalize_execution_backend(requested)
    allowed_all_specs = _matching_specs(target, include_unavailable=True)
    allowed_available_specs = _matching_specs(target, include_unavailable=False)
    allowed_all = [spec.name for spec in allowed_all_specs]
    allowed_available = [spec.name for spec in allowed_available_specs]

    if requested_name in (None, "auto"):
        if not allowed_available_specs:
            raise ValueError(f"No available execution backend for target '{target.kind.name}'. Allowed: {_format_options(allowed_all)}.")
        return allowed_available_specs[0]

    if requested_name not in allowed_all:
        raise ValueError(
            f"Invalid execution backend '{requested}' for target '{target.kind.name}'. "
            f"Allowed: {_format_options(allowed_all)}. Tip: use execution_backend='auto'."
        )
    if requested_name not in allowed_available:
        raise ValueError(
            f"Execution backend '{requested}' requires extra dependencies and is not available now. "
            f"Try one of: {_format_options(allowed_available)}."
        )
    return next(spec for spec in allowed_available_specs if spec.name == requested_name)

