#include <tvm/target/target.h>
#include <tvm/target/target_kind.h>

namespace tvm {

namespace refl = ffi::reflection;

std::string ExtractStringWithPrefix(const std::string &str,
                                    const std::string &prefix) {
  if (str.find(prefix) != 0)
    return "";
  std::size_t pos = prefix.length();
  while (pos < str.length() &&
         (std::isdigit(str[pos]) || std::isalpha(str[pos]))) {
    ++pos;
  }
  return str.substr(prefix.length(), pos - prefix.length());
}

void CheckOrSetAttr(ffi::Map<ffi::String, ffi::Any> *attrs,
                    const ffi::String &name, const ffi::String &value) {
  auto iter = attrs->find(name);
  if (iter == attrs->end()) {
    attrs->Set(name, value);
  } else {
    auto str = (*iter).second.try_cast<ffi::String>();
    TVM_FFI_CHECK(str && str.value() == value, ValueError)
        << "Expects \"" << name << "\" to be \"" << value
        << "\", but gets: " << (*iter).second;
  }
}

/*!
 * \brief Update the attributes in the LLVM MACA target.
 * \param target The Target to update
 * \return The updated attributes
 */
ffi::Map<ffi::String, ffi::Any>
UpdateMACAAttrs(ffi::Map<ffi::String, ffi::Any> target) {
  CheckOrSetAttr(&target, "mtriple", "mxc-metax-macahca");
  // Update -mcpu=xcore1000
  std::string arch = "xcore1000";
  if (target.count("mcpu")) {
    ffi::String mcpu = Downcast<ffi::String>(target.at("mcpu"));
    arch = ExtractStringWithPrefix(mcpu, "xcore");
    TVM_FFI_CHECK(!arch.empty(), ValueError)
        << "MACA target gets an invalid XCORE version: -mcpu=" << mcpu;
  } else {
    if (auto f_get_maca_arch =
            tvm::ffi::Function::GetGlobal("tvm_callback_maca_get_arch")) {
      arch = (*f_get_maca_arch)().cast<std::string>();
    }
    target.Set("mcpu", ffi::String(arch));
  }

  return target;
}

TVM_REGISTER_TARGET_KIND("maca", kDLMACA)
    .add_attr_option<ffi::String>("mcpu")
    .add_attr_option<ffi::String>("mtriple")
    .add_attr_option<ffi::Array<ffi::String>>("mattr")
    .add_attr_option<int64_t>("max_num_threads", refl::DefaultValue(1024))
    .add_attr_option<int64_t>("max_threads_per_block", refl::DefaultValue(1024))
    .add_attr_option<int64_t>("max_shared_memory_per_block",
                              refl::DefaultValue(65536))
    .add_attr_option<int64_t>("thread_warp_size", refl::DefaultValue(64))
    .add_attr_option<int64_t>("max_local_memory_per_block",
                              refl::DefaultValue(4095))
    .set_default_keys({"maca", "gpu"})
    .set_target_canonicalizer(UpdateMACAAttrs);

} // namespace tvm

import pytest

import tilelang
import tilelang.language as T
import tilelang.testing


CUDA_SM86_TARGET = {"kind": "cuda", "arch": "sm_86"}
CUDA_SM90_TARGET = {"kind": "cuda", "arch": "sm_90"}
MACA_TARGET = {"kind": "maca"}


def _barrier_kernel():
    """A minimal kernel whose only special feature is a shared barrier."""

    @T.prim_func
    def main(C: T.Tensor((1,), "float32")):
        with T.Kernel(1, threads=1) as _:
            bar = T.alloc_barrier(1)  # noqa: F841
            C[0] = 0.0

    return main


def _no_barrier_kernel():
    """The same minimal kernel without any barrier, used as a control."""

    @T.prim_func
    def main(C: T.Tensor((1,), "float32")):
        with T.Kernel(1, threads=1) as _:
            C[0] = 0.0

    return main


def _compile(target, kernel_factory=_barrier_kernel):
    """Compile a freshly built kernel for ``target`` with caching disabled."""
    tilelang.disable_cache()
    try:
        return tilelang.compile(kernel_factory(), out_idx=-1, target=target)
    finally:
        tilelang.enable_cache()


@tilelang.testing.requires_cuda
def test_alloc_barrier_rejected_on_pre_hopper_target():
    """T.alloc_barrier() must be rejected with a clear error on sm_86 instead of
    emitting sm_90-only code that fails later inside nvcc."""
    with pytest.raises(ValueError) as exc_info:
        _compile(CUDA_SM86_TARGET)

    message = str(exc_info.value)
    assert "requires sm_90" in message
    assert "sm_86" in message
    # Names the offending primitives so users know what to remove.
    assert "tl_shuffle_elect" in message or "Barrier" in message


@tilelang.testing.requires_cuda
def test_no_barrier_compiles_on_pre_hopper_target():
    """The guard must not fire for pre-Hopper kernels that use no barrier."""
    _compile(MACA_TARGET, kernel_factory=_no_barrier_kernel)


@tilelang.testing.requires_cuda_compute_version_ge(9, 0)
def test_alloc_barrier_allowed_on_hopper_target():
    """The guard must not regress sm_90, where T.alloc_barrier() is valid."""
    _compile(CUDA_SM90_TARGET)


if __name__ == "__main__":
    tilelang.testing.main()

"""Device codegen registry shared by backend packages."""

from __future__ import annotations

from collections.abc import Callable
from dataclasses import dataclass
from importlib import import_module

from tvm import IRModule
from tvm.target import Target

from tilelang import tvm

DeviceCodegenFunc = Callable[[IRModule, Target], IRModule]
TargetPredicate = Callable[[Target], bool]


def global_func_device_codegen(global_func_name: str) -> DeviceCodegenFunc:
    """Create a device codegen callback backed by a TVM global function."""

    def build(mod: IRModule, target: Target) -> IRModule:
        return tvm.ffi.get_global_func(global_func_name)(mod, target)

    return build


@dataclass(frozen=True, slots=True)
class DeviceCodegen:
    """Device codegen entry points for one backend target variant."""

    name: str
    build: DeviceCodegenFunc | None = None
    build_without_compile: DeviceCodegenFunc | None = None
    supports_target: TargetPredicate | None = None

    def matches(self, target: Target) -> bool:
        return True if self.supports_target is None else self.supports_target(target)

    def lower(self, mod: IRModule, target: Target, *, compile_device: bool) -> IRModule:
        build_func = self.build if compile_device else self.build_without_compile
        if build_func is None:
            mode = "with compilation" if compile_device else "without compilation"
            raise ValueError(f"Device codegen '{self.name}' for target '{target.kind.name}' does not support lowering {mode}")
        return build_func(mod, target)


_DEVICE_CODEGENS: dict[str, list[DeviceCodegen]] = {}
_LAZY_DEVICE_CODEGENS: dict[str, str] = {}
_LOADED_DEVICE_CODEGENS: set[str] = set()


def register_device_codegen(
    target_kind: str,
    codegen: DeviceCodegen,
    *,
    override: bool = False,
) -> DeviceCodegen:
    """Register a device codegen entry for a target kind."""

    codegens = _DEVICE_CODEGENS.setdefault(target_kind, [])
    if override:
        codegens[:] = [item for item in codegens if item.name != codegen.name]
    elif any(item.name == codegen.name for item in codegens):
        raise ValueError(f"Device codegen {codegen.name!r} is already registered for target kind {target_kind!r}")
    codegens.append(codegen)
    return codegen


def register_lazy_device_codegen(target_kind: str, import_path: str) -> None:
    """Register a backend module to import when its target kind is first used."""

    _LAZY_DEVICE_CODEGENS[target_kind] = import_path
    _LOADED_DEVICE_CODEGENS.discard(target_kind)


def _ensure_device_codegens_loaded(target_kind: str) -> None:
    if target_kind in _LOADED_DEVICE_CODEGENS:
        return
    import_path = _LAZY_DEVICE_CODEGENS.get(target_kind)
    if import_path is not None:
        import_module(import_path)
    _LOADED_DEVICE_CODEGENS.add(target_kind)


def _matching_device_codegens(target: Target) -> list[DeviceCodegen]:
    target_kind = target.kind.name
    _ensure_device_codegens_loaded(target_kind)
    return [codegen for codegen in _DEVICE_CODEGENS.get(target_kind, ()) if codegen.matches(target)]


def allowed_device_codegens_for_target(target: Target) -> list[str]:
    """Return matching device codegen names for a target."""

    return [codegen.name for codegen in _matching_device_codegens(target)]


def _format_codegen_names(codegens: list[DeviceCodegen]) -> str:
    names = [codegen.name for codegen in codegens]
    return ", ".join(names) if names else "<none>"


def resolve_device_codegen(target: Target) -> DeviceCodegen:
    """Resolve a device codegen entry from a TVM target."""

    matches = _matching_device_codegens(target)
    if not matches:
        target_kind = target.kind.name
        options = _format_codegen_names(_DEVICE_CODEGENS.get(target_kind, []))
        raise ValueError(f"No device codegen registered for target '{target_kind}'. Available: {options}.")
    return matches[0]

